// The team's own tests for src/bopis/eligibility.js, written in sprints 1 to 3. They record how the code behaves today.
// Lab fixture: please do not edit this file.
import test from 'node:test';
import assert from 'node:assert/strict';
import { isBopisEligible } from '../../src/bopis/eligibility.js';

const shirt = { sku: 'A-100', name: 'Cotton shirt', category: 'apparel', weightKg: 0.3, price: 24, shelfLifeDays: null };

test('an ordinary item is eligible', () => {
  assert.equal(isBopisEligible(shirt), true);
});

test('an item with no stock information is still eligible', () => {
  assert.equal(isBopisEligible(shirt, {}), true);
});

test('a gift card is not eligible', () => {
  assert.equal(isBopisEligible({ sku: 'G-1', category: 'gift-card', price: 50 }), false);
});

test('a hazmat item is not eligible', () => {
  assert.equal(isBopisEligible({ ...shirt, sku: 'H-1', category: 'household', hazmat: true }), false);
});

test('an age-restricted item needs the age to be verified', () => {
  const wine = { sku: 'W-1', category: 'alcohol', price: 18, ageRestricted: true };
  assert.equal(isBopisEligible(wine), false);
  assert.equal(isBopisEligible(wine, { ageVerified: true }), true);
});

test('six units are fine, seven are too many', () => {
  assert.equal(isBopisEligible(shirt, { quantity: 6 }), true);
  assert.equal(isBopisEligible(shirt, { quantity: 7 }), false);
});

test('the store needs the quantity plus a buffer in stock', () => {
  assert.equal(isBopisEligible(shirt, { quantity: 1, storeStock: 3 }), true);
  assert.equal(isBopisEligible(shirt, { quantity: 1, storeStock: 2 }), false);
  assert.equal(isBopisEligible(shirt, { quantity: 4, storeStock: 6 }), true);
  assert.equal(isBopisEligible(shirt, { quantity: 4, storeStock: 5 }), false);
});

test('nothing is eligible while the store is closed', () => {
  assert.equal(isBopisEligible(shirt, { storeOpen: false }), false);
});

test('the answer is always a boolean', () => {
  for (const ctx of [{}, { quantity: 9 }, { storeOpen: false }, { storeStock: 0 }]) {
    assert.equal(typeof isBopisEligible(shirt, ctx), 'boolean');
  }
});
